#include <algorithm>
#include <cassert>
#include <cstdint>
#include <cstring>
#include <cstdio>
#include <chrono>
#include <future>
#include <vector>
struct State {int32_t children,views,buffer;uint32_t pad0;int32_t chunk;uint32_t pad1;uint64_t offset;bool allocated;uint8_t pad2[7];};
static_assert(sizeof(State)==40 && offsetof(State,allocated)==32);
struct Context;
struct Node {State state{};Context *context{};int id{},op{1};uint32_t flags{};Node *owner{};Node *sources[10]{};};
struct Context {std::vector<Node> storage;std::vector<Node*> nodes,leafs;std::vector<int> node_buffers,leaf_buffers;std::vector<uint64_t> events;};
extern "C" void fg_selfhost_graph_plan(void*,const void*,int,const void*,int,const int*,const int*,int,unsigned,int,bool);
static Node *node(uint64_t x){assert(x);return reinterpret_cast<Node*>(x);}
extern "C" void *fg_graph_hash(uint64_t a,uint64_t n){assert(node(n)->context==reinterpret_cast<Context*>(a));return &node(n)->state;}
extern "C" uint64_t fg_graph_source(uint64_t n,int64_t i){assert(i>=0&&i<10);return reinterpret_cast<uint64_t>(node(n)->sources[i]);}
extern "C" uint64_t fg_graph_owner(uint64_t n){assert(node(n)->owner);return reinterpret_cast<uint64_t>(node(n)->owner);}
extern "C" bool fg_graph_is_view(uint64_t n){return node(n)->owner!=nullptr;}
extern "C" uint32_t fg_graph_flags(uint64_t n){return node(n)->flags;}
extern "C" int32_t fg_graph_op(uint64_t n){return node(n)->op;}
static void allocate(Context *c,Node *n,int b){c->events.push_back((UINT64_C(1)<<60)|(uint64_t(n->id)<<32)|uint32_t(b));if(n->state.allocated)return;if(n->owner){if(!n->owner->state.allocated)allocate(c,n->owner,b);return;}n->state.allocated=true;n->state.buffer=b;}
static void release(Context *c,Node *n){c->events.push_back((UINT64_C(2)<<60)|uint64_t(n->id));if(n->flags&2)return;assert(n->state.allocated);n->state.allocated=false;}
extern "C" void fg_graph_allocate(uint64_t a,uint64_t n,int32_t b){allocate(reinterpret_cast<Context*>(a),node(n),b);}
extern "C" void fg_graph_release(uint64_t a,uint64_t n){release(reinterpret_cast<Context*>(a),node(n));}
extern "C" void fg_graph_verify(const void *p,int32_t c,int32_t v,bool allocated,int32_t kind,int32_t action,bool is_view){const auto&s=*static_cast<const State*>(p);int expected=0;if(kind==0)v++;else if(kind==1)c++;else if(kind==2){c--;if(c==0&&v==0)expected=is_view?2:allocated?1:0;}else if(kind==3){v--;expected=v==0&&c==0&&allocated;}else assert(false);assert(s.children==c&&s.views==v&&s.allocated==allocated&&action==expected);}
static void initialize(Context &c,unsigned seed,int count,bool buffers){c.storage.resize(count+3);c.events.reserve(8192);uint64_t rng=seed;auto next=[&](){rng=rng*UINT64_C(6364136223846793005)+1;return unsigned(rng>>32);};for(int i=0;i<count+3;i++){auto&n=c.storage[i];n.id=i;n.context=&c;n.state.offset=i*4096;n.state.chunk=i%3;n.state.buffer=-1;std::fill(std::begin(n.state.pad2),std::end(n.state.pad2),0xA5);if(i<3){n.flags=1;n.op=0;c.leafs.push_back(&n);continue;}if(next()%4==0){int k=next()%i;while(c.storage[k].owner)k=(k+1)%i;n.owner=&c.storage[k];n.sources[0]=n.owner;}else{int parents=1+next()%4;for(int j=0;j<parents;j++)n.sources[j]=&c.storage[next()%i];}if(next()%9==0)n.flags|=1;if(i==count+2||next()%17==0)n.flags|=2;c.nodes.push_back(&n);}if(buffers){for(auto*n:c.nodes)c.node_buffers.push_back(n->id%3);for(auto*n:c.leafs)c.leaf_buffers.push_back(n->id%3);}}
static int buffer(const std::vector<int>&b,size_t i){return b.empty()?0:b[i];}
static void native(Context &c){for(size_t i=0;i<c.leafs.size();i++)allocate(&c,c.leafs[i],buffer(c.leaf_buffers,i));for(size_t i=0;i<c.nodes.size();i++){Node*n=c.nodes[i];if(n->owner&&n->op!=0)n->owner->state.views++;if(n->flags&1)allocate(&c,n,buffer(c.node_buffers,i));for(auto*p:n->sources)if(p){p->state.children++;if(p->flags&1)allocate(&c,p,buffer(c.node_buffers,i));}}for(size_t i=0;i<c.nodes.size();i++){Node*n=c.nodes[i];for(auto*p:n->sources)if(p)allocate(&c,p,buffer(c.node_buffers,i));allocate(&c,n,buffer(c.node_buffers,i));for(auto*p:n->sources)if(p){auto&s=p->state;s.children--;if(s.children==0&&s.views==0){if(p->owner){auto&o=p->owner->state;o.views--;if(o.views==0&&o.children==0&&o.allocated)release(&c,p->owner);}else if(s.allocated)release(&c,p);}}}}
static void goose(Context &c,bool verify){fg_selfhost_graph_plan(&c,c.nodes.data(),int(c.nodes.size()),c.leafs.data(),int(c.leafs.size()),c.node_buffers.empty()?nullptr:c.node_buffers.data(),c.leaf_buffers.empty()?nullptr:c.leaf_buffers.data(),10,1,0,verify);}
static size_t check(unsigned seed,int count,bool buffers){Context a,b;initialize(a,seed,count,buffers);initialize(b,seed,count,buffers);native(a);goose(b,true);if(a.events!=b.events){std::fprintf(stderr,"Mismatch seed=%u count=%d buffers=%d events native=%zu goose=%zu\n",seed,count,buffers,a.events.size(),b.events.size());for(size_t k=0;k<std::min(a.events.size(),b.events.size());k++)if(a.events[k]!=b.events[k]){std::fprintf(stderr,"first index=%zu native=%llx goose=%llx\n",k,(unsigned long long)a.events[k],(unsigned long long)b.events[k]);for(size_t j=k>3?k-3:0;j<std::min(std::min(a.events.size(),b.events.size()),k+8);j++)std::fprintf(stderr,"%zu %llx %llx\n",j,(unsigned long long)a.events[j],(unsigned long long)b.events[j]);break;}for(size_t j=0;j<a.storage.size();j++){const auto&x=a.storage[j];const auto&y=b.storage[j];std::fprintf(stderr,"node %zu native child=%d views=%d allocated=%d goose child=%d views=%d allocated=%d sources=",j,x.state.children,x.state.views,x.state.allocated,y.state.children,y.state.views,y.state.allocated);for(auto*q:x.sources)if(q)std::fprintf(stderr,"%d,",q->id);std::fprintf(stderr,"\n");}for(size_t j=0;j<a.events.size();j++)std::fprintf(stderr,"event %zu %llx %llx\n",j,(unsigned long long)a.events[j],(unsigned long long)(j<b.events.size()?b.events[j]:0));std::abort();}for(size_t i=0;i<a.storage.size();i++)assert(std::memcmp(&a.storage[i].state,&b.storage[i].state,sizeof(State))==0);return a.events.size();}
int main(int argc,char**){size_t events=0;for(int i=0;i<200;i++)events+=check(20261107+i,i%129,i%2);std::vector<std::future<size_t>> jobs;for(int t=0;t<8;t++)jobs.push_back(std::async(std::launch::async,[t](){size_t n=0;for(int i=0;i<16;i++)n+=check(9000+t*16+i,64+(i%64),i%2);return n;}));for(auto&f:jobs)events+=f.get();std::printf("{\"status\":\"PASS\",\"single_graph_cases\":200,\"eight_thread_graph_cases\":128,\"ordered_service_events_checked\":%zu,\"all_final_state_bytes_equal\":true,\"mock_services_not_physical_allocator\":true}\n",events);if(argc>1){for(int pass=0;pass<7;pass++)for(int mode=0;mode<2;mode++){int use_goose=(pass+mode)%2;double ns=0;size_t sum=0;for(int i=0;i<100;i++){Context c;initialize(c,20261107+i,128,true);auto begin=std::chrono::steady_clock::now();if(use_goose)goose(c,false);else native(c);ns+=std::chrono::duration<double,std::nano>(std::chrono::steady_clock::now()-begin).count();sum+=c.events.size();}std::printf("{\"pass\":%d,\"goose\":%d,\"ns_graph\":%.3f,\"events\":%zu,\"preliminary\":true}\n",pass,use_goose,ns/100,sum);}}}
